 1→/**
 2→ * Mixed Workload Scenario
 3→ *
 4→ * Simulates realistic usage: folder CRUD, file uploads, renames, moves, deletes
 5→ * with weighted probabilities. Tests the system under representative load.
 6→ */
 7→
 8→import { describe, it, afterAll } from 'vitest';
 9→import {
10→  createClientPool,
11→  destroyClientPool,
12→  aggregateAndReport,
13→  type PoolClient,
14→} from '../harness/client-pool';
15→import { runMixedWorkload } from '../workloads/mixed-workload';
16→
17→const NUM_CLIENTS = parseInt(process.env.LOAD_TEST_CLIENTS ?? '5', 10);
18→const OPS_PER_CLIENT = 45;
19→
20→describe('Mixed Workload', () => {
21→  let pool: PoolClient[] = [];
22→
23→  afterAll(async () => {
24→    await destroyClientPool(pool);
25→  });
26→
27→  it(`${NUM_CLIENTS} clients × ${OPS_PER_CLIENT} mixed ops`, async () => {
28→    pool = await createClientPool({
29→      clientCount: NUM_CLIENTS,
30→      label: 'mixed',
31→    });
32→
33→    const results = await Promise.allSettled(
34→      pool.map((pc) => {
35→        pc.metrics.start();
36→        return runMixedWorkload(pc, {
37→          totalOps: OPS_PER_CLIENT,
38→          weights: {
39→            createFolder: 2,
40→            uploadFile: 4,
41→            renameItem: 1,
42→            moveItem: 1,
43→            deleteItem: 1,
44→          },
45→        }).finally(() => pc.metrics.stop());
46→      })
47→    );
48→
49→    const succeeded = results.filter((r) => r.status === 'fulfilled').length;
50→    console.log(`\nClients completed: ${succeeded}/${pool.length}`);
51→
52→    await aggregateAndReport('Mixed Workload', pool);
53→  });
54→});
