 1→/**
 2→ * Spike Test Scenario
 3→ *
 4→ * Starts with a baseline of 2 clients, then bursts to 20 clients.
 5→ * Measures recovery time — how long until latencies return to baseline.
 6→ */
 7→
 8→import { describe, it, afterAll } from 'vitest';
 9→import {
10→  createClientPool,
11→  destroyClientPool,
12→  aggregateAndReport,
13→  type PoolClient,
14→} from '../harness/client-pool';
15→import { runFolderWorkload } from '../workloads/folder-workload';
16→
17→const BASELINE_CLIENTS = 2;
18→const BURST_CLIENTS = parseInt(process.env.LOAD_TEST_CLIENTS ?? '20', 10);
19→const BASELINE_CYCLES = 10;
20→const BURST_CYCLES = 30;
21→
22→describe('Spike Test', () => {
23→  let baselinePool: PoolClient[] = [];
24→  let burstPool: PoolClient[] = [];
25→
26→  afterAll(async () => {
27→    await destroyClientPool(baselinePool);
28→    await destroyClientPool(burstPool);
29→  });
30→
31→  it(`baseline ${BASELINE_CLIENTS} clients → burst ${BURST_CLIENTS} clients`, async () => {
32→    // Phase 1: Baseline
33→    console.log('\n--- Phase 1: Baseline ---');
34→    baselinePool = await createClientPool({
35→      clientCount: BASELINE_CLIENTS,
36→      label: 'spike-baseline',
37→    });
38→
39→    await Promise.allSettled(
40→      baselinePool.map((pc) => {
41→        pc.metrics.start();
42→        return runFolderWorkload(pc, { cycles: BASELINE_CYCLES }).finally(() => pc.metrics.stop());
43→      })
44→    );
45→
46→    const baselineMetrics = await aggregateAndReport('Spike Test - Baseline', baselinePool);
47→
48→    // Phase 2: Burst
49→    console.log('\n--- Phase 2: Burst ---');
50→    burstPool = await createClientPool({
51→      clientCount: BURST_CLIENTS,
52→      label: 'spike-burst',
53→    });
54→
55→    await Promise.allSettled(
56→      burstPool.map((pc) => {
57→        pc.metrics.start();
58→        return runFolderWorkload(pc, { cycles: BURST_CYCLES }).finally(() => pc.metrics.stop());
59→      })
60→    );
61→
62→    const burstMetrics = await aggregateAndReport('Spike Test - Burst', burstPool);
63→
64→    // Compare baseline vs burst latencies
65→    console.log('\n--- Latency Comparison (p95) ---');
66→    for (const baseOp of baselineMetrics) {
67→      const burstOp = burstMetrics.find((b) => b.operation === baseOp.operation);
68→      if (burstOp) {
69→        const degradation = (
70→          ((burstOp.latency.p95 - baseOp.latency.p95) / baseOp.latency.p95) *
71→          100
72→        ).toFixed(0);
73→        console.log(
74→          `  ${baseOp.operation}: baseline=${Math.round(baseOp.latency.p95)}ms → burst=${Math.round(burstOp.latency.p95)}ms (${degradation}% change)`
75→        );
76→      }
77→    }
78→  });
79→});
