 1→/**
 2→ * Sustained Load Scenario
 3→ *
 4→ * N clients running at a steady rate for a configurable duration.
 5→ * Tests latency stability over time — detects memory leaks, connection
 6→ * pool exhaustion, and other time-dependent degradation.
 7→ */
 8→
 9→import { describe, it, afterAll } from 'vitest';
10→import {
11→  createClientPool,
12→  destroyClientPool,
13→  aggregateAndReport,
14→  type PoolClient,
15→} from '../harness/client-pool';
16→
17→const NUM_CLIENTS = parseInt(process.env.LOAD_TEST_CLIENTS ?? '5', 10);
18→const DURATION_SEC = parseInt(process.env.LOAD_TEST_DURATION ?? '300', 10);
19→const OPS_PER_SEC_PER_CLIENT = 2;
20→
21→describe('Sustained Load', () => {
22→  let pool: PoolClient[] = [];
23→
24→  afterAll(async () => {
25→    await destroyClientPool(pool);
26→  });
27→
28→  it(`${NUM_CLIENTS} clients × ${OPS_PER_SEC_PER_CLIENT} ops/sec for ${DURATION_SEC}s`, async () => {
29→    pool = await createClientPool({
30→      clientCount: NUM_CLIENTS,
31→      label: 'sustained',
32→    });
33→
34→    const endTime = Date.now() + DURATION_SEC * 1000;
35→
36→    const results = await Promise.allSettled(
37→      pool.map((pc) => runSustainedClient(pc, endTime, OPS_PER_SEC_PER_CLIENT))
38→    );
39→
40→    const succeeded = results.filter((r) => r.status === 'fulfilled').length;
41→    console.log(`\nClients completed: ${succeeded}/${pool.length}`);
42→
43→    await aggregateAndReport('Sustained Load', pool);
44→  });
45→});
46→
47→async function runSustainedClient(
48→  pc: PoolClient,
49→  endTime: number,
50→  opsPerSec: number
51→): Promise<void> {
52→  const { client, rootIpnsName, metrics } = pc;
53→  metrics.start();
54→
55→  const intervalMs = 1000 / opsPerSec;
56→  let folderCounter = 0;
57→
58→  while (Date.now() < endTime) {
59→    const opStart = Date.now();
60→
61→    try {
62→      // Alternate between folder create and delete to keep state manageable
63→      const name = `sustained-${pc.id}-${folderCounter++}`;
64→
65→      const folder = await metrics.measure('createFolder', () =>
66→        client.createFolder(rootIpnsName, name)
67→      );
68→
69→      // Small file upload
70→      const data = new Uint8Array(1024);
71→      crypto.getRandomValues(data);
72→      await metrics.measure(
73→        'uploadFile',
74→        () => client.uploadFile(rootIpnsName, data, `${name}.bin`, 'application/octet-stream'),
75→        1024
76→      );
77→
78→      // Cleanup to prevent state bloat
79→      const folderState = client.getFolderTree().get(rootIpnsName);
80→      const fileChild = folderState?.children.find((c) => c.name === `${name}.bin`);
81→      if (fileChild) {
82→        await metrics.measure('deleteItem', () => client.deleteItem(rootIpnsName, fileChild.id));
83→      }
84→      await metrics.measure('deleteItem', () => client.deleteItem(rootIpnsName, folder.id));
85→    } catch {
86→      // Non-fatal — continue the sustained load
87→    }
88→
89→    // Wait for next interval
90→    const elapsed = Date.now() - opStart;
91→    const wait = Math.max(0, intervalMs - elapsed);
92→    if (wait > 0) {
93→      await new Promise((r) => setTimeout(r, wait));
94→    }
95→  }
96→
97→  metrics.stop();
98→}
